"use strict";

const util = require("util");
const { EventEmitter, once } = require("events");

exports.summarize = async function summarize() {
  const emitter = new EventEmitter();
  const eventPromise = once(emitter, "data");
  const doubleAsync = util.promisify((value, callback) => callback(null, value * 2));

  Promise.resolve().then(() => {
    emitter.emit("data", { value: 7 }, "ready");
  });

  const [payload, label] = await eventPromise;
  const formatted = util.format("%s/%d", label, await doubleAsync(payload.value));
  const inspected = util.inspect({ label, value: payload.value }, {
    breakLength: Infinity,
    sorted: true
  });

  return [
    "utilevents",
    formatted,
    inspected.includes("label: 'ready'"),
    inspected.includes("value: 7")
  ].join(":");
};
